// Assembles the deployable folder release/ from the standalone build.
// Layout on the server (application root of "Setup Node.js App"):
//   server.js          Passenger startup file, generated by Next standalone
//   .next/             server bundle and static assets
//   node_modules/      traced runtime dependencies only
//   public/            public files
//   dist/cron.js       cron entry point, dist/migrate.js migration runner
//   drizzle/           SQL migrations
import { cpSync, existsSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";

const out = "release";
const required = [".next/standalone/server.js", "dist/cron.js", "dist/migrate.js"];
for (const file of required) {
  if (!existsSync(file)) {
    console.error(`Fichier manquant : ${file}. Lancez pnpm build puis pnpm build:cron.`);
    process.exit(1);
  }
}

rmSync(out, { recursive: true, force: true });
cpSync(".next/standalone", out, { recursive: true, verbatimSymlinks: true });
cpSync(".next/static", `${out}/.next/static`, { recursive: true });
cpSync("public", `${out}/public`, { recursive: true });
cpSync("dist", `${out}/dist`, { recursive: true });
cpSync("drizzle", `${out}/drizzle`, { recursive: true });

// Next file tracing misses the platform specific native bindings of
// @node-rs/argon2 (optional dependencies): copy the ones installed for the
// build machine, which is Linux x64 in CI like the cPanel host.
// node_modules is hoisted (pnpm nodeLinker: hoisted), so bindings sit next to the main package.
const scopeDir = "node_modules/@node-rs";
let bindings = 0;
for (const name of existsSync(scopeDir) ? readdirSync(scopeDir) : []) {
  if (!/^argon2-/.test(name)) continue;
  cpSync(`${scopeDir}/${name}`, `${out}/node_modules/@node-rs/${name}`, { recursive: true, dereference: true });
  bindings++;
}
if (bindings === 0) {
  console.error("Aucun binaire natif @node-rs/argon2 trouvé : la connexion échouerait en production.");
  process.exit(1);
}

// Never ship local environment files.
for (const file of [".env", ".env.local", ".env.production.local"]) {
  rmSync(`${out}/${file}`, { force: true });
}

let commit = "unknown";
try {
  commit = execSync("git rev-parse --short HEAD").toString().trim();
} catch {
  // Not a git checkout.
}
writeFileSync(`${out}/RELEASE`, `${commit}\n${new Date().toISOString()}\n`);
console.log(`Release assemblée dans ${out}/ (${commit})`);
